export function sideMeaning(q){const side=q?.source?.native_side?.toUpperCase();return['YES','NO','LONG','SHORT'].includes(side)?side:'';}
const shortReason=reason=>{const r=String(reason||'Inputs needed').toLowerCase();if(/capacity/.test(r))return'Binding capacity';if(/fee|cost|mandatory|charge/.test(r))return'Fee needed';if(/reference|pinnacle/.test(r))return'Reference needed';if(/age|old|expired|clock/.test(r))return'Too old / age unknown';if(/probability|partition|tie|push/.test(r))return'Probability needed';if(/depth/.test(r))return'Depth needed';if(/mapping|identity|link/.test(r))return'Mapping needed';if(/payout|settlement/.test(r))return'Payout needed';if(/grid|increment|quantity/.test(r))return'Legal size needed';if(/separate estimate/.test(r))return'Separate bases';return'Inputs needed';};
