            for(const q of qs){const button=priorButtons.get(q.id)||el('button',undefined,'price-button');button.type='button';button.dataset.quoteId=q.id;button.review={event,...row.contexts[q.id],quote:q,mode:payload.mode};button.onclick=()=>onSelect(button.review);const raw=Object.values(all).flat().filter(v=>v.display?.conversion?.decimal_approx).sort((a,b)=>compareFunded({buffered_return_percent:a.display.conversion.decimal_approx},{buffered_return_percent:b.display.conversion.decimal_approx}))[0];button.dataset.bestRaw=String(raw?.id===q.id);fillPrice(button,q);button.classList.toggle('selected',q.id===selectedId);cell.append(button);buttons.set(q.id,{button,q,quotes:all});}
            line.append(cell);
