          const metric=el('td');metric.dataset.label='Buffered estimate';const inspect=el('button',funded?fundedText(chosen?.calculations?.funded_estimate):metricText(net),'net-cell');inspect.id='net-'+row.outcome.id;inspect.type='button';inspect.dataset.selectedVenue=best?.venue||net?.selected_venue||'';if(chosen)inspect.onclick=()=>onSelect({event,...row.contexts[chosen.id],quote:chosen,mode:payload.mode});else inspect.disabled=true;inspect.append(el('small',funded?(best?'Best estimated value · '+venues[best.venue]+' · '+(best.calculations.funded_estimate.conditioning==='modeled_conditional'?'Conditional':'Complete model'):'Inspect as-of / unavailable results'):net.eligible?(venues[net.selected_venue]+' · Estimated'):'Inspect Details'));if(funded)inspect.append(el('small',fundedNote(chosen?.calculations?.funded_estimate)));metric.append(inspect);line.append(metric);body.append(line);
