export const reconcileChangedBoard=(root,payload,filters,onSelect,selectedId)=>reconcileBoard(root,payload,filters,onSelect,selectedId);
const section=(root,title)=>{const n=el('section',undefined,'detail-section');n.append(el('h3',title));root.append(n);return n;};
const fact=(root,label,value)=>{const line=el('p');line.append(el('strong',label+': '),el('span',value===null||value===undefined?'Unknown':typeof value==='string'?value:JSON.stringify(value)));root.append(line);};
